mapper.select:
SELECT id, org_path, version
FROM tab_org
WHERE org_path = #{prefix}
   OR (LEFT(org_path, CHAR_LENGTH(#{prefix})) = #{prefix}
       AND SUBSTRING(org_path, CHAR_LENGTH(#{prefix}) + 1, 1) = '/')

mapper.update:
UPDATE tab_org
SET org_name_path = CONCAT(#{newPrefix}, SUBSTRING(org_name_path, CHAR_LENGTH(#{oldPrefix}) + 1)),
    update_by = #{updateBy},
    update_time = #{updateTime}
WHERE org_name_path = #{oldPrefix}
   OR (LEFT(org_name_path, CHAR_LENGTH(#{oldPrefix})) = #{oldPrefix}
       AND SUBSTRING(org_name_path, CHAR_LENGTH(#{oldPrefix}) + 1, 1) = '/')

mapper.select:
SELECT COUNT(*)
FROM tab_org
WHERE status != -1000
AND ${column} = #{value}
AND id != #{excludeId}

SELECT * FROM tab_org

    AND update_time >= #{updateTimeFrom}
    AND update_time <= #{updateTimeTo}

        AND id = -1

            AND id IN
            #{itemId}



        AND 1 = 0

            AND code IN
            #{itemCode}



        AND id = -1

            AND id IN
            #{orgId}



ORDER BY update_time ASC, id ASC
LIMIT #{offset}, #{limit}

SELECT * FROM tab_org

    AND id > #{lastId}

        AND id = -1

            AND id IN
            #{orgId}



ORDER BY id ASC
LIMIT #{batchSize}
